importScripts('vendor/lame.min.js');
onmessage=({data})=>{try{const {left,right,sampleRate}=data,encoder=new lamejs.Mp3Encoder(2,sampleRate,192),chunks=[],block=1152;for(let at=0;at<left.length;at+=block){const n=Math.min(block,left.length-at),l=new Int16Array(n),r=new Int16Array(n);for(let i=0;i<n;i++){l[i]=Math.max(-1,Math.min(1,left[at+i]))*32767;r[i]=Math.max(-1,Math.min(1,right[at+i]))*32767}const b=encoder.encodeBuffer(l,r);if(b.length)chunks.push(new Uint8Array(b));if(at%(block*100)===0)postMessage({progress:at/left.length});}const b=encoder.flush();if(b.length)chunks.push(new Uint8Array(b));postMessage({done:true,chunks},chunks.map(b=>b.buffer));}catch(e){postMessage({error:'MP3 encoding failed: '+e.message})}};
